// <auto-generated/>
using System;
using System.Drawing;
using CargoWise.Types;
using CargoWiseOne.ResourceStrings;
using Enterprise.Registry.Business.Warehouse;
using Enterprise.Warehouse.Transactions.Business;
using Enterprise.Warehouse.Transactions.GUI.Common;
using Enterprise.Warehouse.Transactions.GUI.WhsPicksAwaitingReplenishment;
using Enterprise.ZArchitecture.GUI;

namespace Enterprise.Warehouse.Transactions.GUI
{
	public partial class PickHeaderUserControl : ZUserControl
	{
		#region Constructors

		public PickHeaderUserControl()
		{
			InitializeComponent();
		}

		WhsPick Pick => (WhsPick)CurrentDataItem;

		#endregion

		#region Events

		protected override void OnCurrentDataItemChanging(EventArgs e)
		{
			base.OnCurrentDataItemChanging(e);
			if (Pick != null)
			{
				Pick.WP_PercentageCompleteInfo.ValueChanged -= new EventHandler(WP_PercentageCompleteInfo_ValueChanged);
				Pick.WP_IsAwaitingReplenishmentInfo.ValueChanged -= new EventHandler(WP_IsAwaitingReplenishmentInfo_ValueChanged);
			}
		}

		protected override void OnCurrentDataItemChanged(EventArgs e)
		{
			base.OnCurrentDataItemChanged(e);
			if (Pick != null)
			{
				Pick.WP_PercentageCompleteInfo.ValueChanged += new EventHandler(WP_PercentageCompleteInfo_ValueChanged);
				OnPercentageCompleteChanged();
				Pick.WP_IsAwaitingReplenishmentInfo.ValueChanged += new EventHandler(WP_IsAwaitingReplenishmentInfo_ValueChanged);
				SetVisibilityForAwaitingReplenishmentButton();
			}
		}

		void WP_IsAwaitingReplenishmentInfo_ValueChanged(object sender, EventArgs e)
		{
			SetVisibilityForAwaitingReplenishmentButton();
		}

		void WP_PercentageCompleteInfo_ValueChanged(object sender, EventArgs e)
		{
			OnPercentageCompleteChanged();
		}

		void OnPercentageCompleteChanged()
		{
			if (WarehouseDataRegistry.Instance.DisplayPickStatus.Value)
			{
				ShowPieChart();
				UpdatePieChart();
			}
			else
			{
				HidePieChart();
			}
		}

		void DisplayAwaitingReplenishmentPicksButton_Click(object sender, EventArgs e)
		{
			var form = new WhsPicksAwaitingReplenishmentForm(Pick);
			ZFormModaliser.Show(form, ParentForm);
		}

		#endregion

		#region Show/Hide PieChart

		void ShowPieChart()
		{
			PieChartBox.Visible = true;
			PickStatusChartUnavailableLabel.Visible = false;
		}

		void HidePieChart()
		{
			PickStatusChartUnavailableLabel.Visible = true;
			PieChartBox.Visible = false;
		}

		#endregion

		#region UpdatePieChart

		void UpdatePieChart()
		{
			var percentageCompleteColour = Color.FromArgb(120, 209, 104);
			var percentageCompleteData = GetPercentageComplete();
			var percentageCompleteLegend = Res.GetString("c71f79fc-28ef-4e83-b088-b52a655defc6", "{0:0}% Completed", percentageCompleteData);

			var percentageRemainingColour = Color.FromArgb(244, 135, 123);
			var percentageRemainingData = 100 - percentageCompleteData;
			var percentageRemainingLegend = Res.GetString("93be99a0-a9c7-4e22-b300-21635c02a978", "{0:0}% Pending", percentageRemainingData);

			var dataPoints = new[] {
				new ChartDataPoint(percentageCompleteColour, percentageCompleteLegend, percentageCompleteData),
				new ChartDataPoint(percentageRemainingColour, percentageRemainingLegend, percentageRemainingData)
			};

			PieChartBox.UpdateLegendColoursAndData(dataPoints);
		}

		double GetPercentageComplete()
		{
			var percentageComplete = (Pick != null) ? Pick.WP_PercentageComplete : (ZByte)0;
			return percentageComplete;
		}

		#endregion

		#region SetVisibilityForAwaitingReplenishmentButton

		public void SetVisibilityForAwaitingReplenishmentButton()
		{
			DisplayAwaitingReplenishmentPicksButton.Visible = Pick.WP_IsAwaitingReplenishment;
		}

		#endregion
	}
}
